          "en": "For example, an eligible person with a close family member who has chronic hepatitis B may receive screening under the Scheme if the other conditions are met.",
          "zh": "例如，如果一名合資格人士有近親患有慢性乙型肝炎，而本人亦符合其他條件，便可能透過計劃接受篩查。"
