          "en": "The Community Drug Formulary is intended to help eligible patients obtain designated medicines in the community at prices below normal market levels under the relevant arrangements.",
          "zh": "社區藥物名冊旨在讓合資格病人在相關安排下，在社區以低於一般市場水平的價格取得指定藥物。"
