          "en": "The Hospital Authority Drug Formulary is the system used by the Hospital Authority to organise medicines according to clinical use, evidence, and funding arrangements.",
          "zh": "醫院管理局藥物名冊是醫管局按臨床用途、證據和資助安排管理藥物的制度。"
